def refs(text):return ['f'+n for n in text.split(',')]
entries=[]
assert set(cases)==set(range(len(concepts)))
for i,c in enumerate(concepts):
    brief=next(r for r in briefs if (r['concept_id'],r['path_id'])==(c['concept_id'],c['path_id']))
    assert depths[c['concept_id'],c['path_id']]['depth_tier']=='core'
    facts=brief['evidence']['required_facts']
    valid={f['id'] for f in facts}
    intro,example,contrast,level,mode,reason=cases[i]
    blocks=[]
    def block(purpose,title,text,ids):
        assert set(ids)<=valid,(i,ids,valid)
        blocks.append(dict(id='tb'+str(len(blocks)+1),purpose=purpose,title=title,content=text,fact_ids=ids))
    block('intro',c['toc_location']['tile_title'],intro,[])
    # Consecutive facts are source-authored in bounded workflow order. Group
    # them as paragraphs rather than displaying a list of fragment cards.
    for start in range(0,len(facts),3):
        group=facts[start:start+3]
        text=' '.join(overrides.get((i,f['id']),f['statement']) for f in group)
        purpose='definition' if start==0 and i in {0,7,9,19,20,33,60,80,81,82} else 'mechanism'
        block(purpose,'The working rule' if start==0 else 'Apply and verify',text,[f['id'] for f in group])
    block('example','A bounded work example',example,refs(example_refs[i]))
    block('misconception','A distinction to keep',contrast,refs(contrast_refs[i]))
    if reason is None:
        reason='A live fixture with visible intermediate state and acceptance checks would make this distinction concrete: '+c['central_mental_model']
    notes=[
        'Start with the concrete fixture and the declared contract; keep the explanation within this tile: '+c['toc_location']['tile_title']+'.',
        'Use the registered prerequisite preparation rather than reteaching general Python, statistics, software engineering or cloud administration. This path assumes those foundations; ownership remains bounded to the supplied ML task and existing authorized runtime.',
        'Declared direct prerequisites: '+(', '.join(c['direct_prerequisite_ids']) if c['direct_prerequisite_ids'] else 'none within this path')+'. Use these as preparation, not additional learning targets. No forward-preview concepts are taught.',
        'All numeric values and short names in the work example are illustrative fixture data, not observed production results. Retain each source rule, qualifier, declared budget and policy boundary.'
    ]
    entries.append(dict(concept_id=c['concept_id'],path_id=c['path_id'],teaching_blocks=blocks,video_need=dict(level=level,reason=reason,preferred_visual_modes=[] if level=='NONE' else [mode]),teaching_notes=notes))
