metadata=dict(artifact_type='glossary_pass_a',artifact_version='1.0.0',schema_version='1.0.0',batch_id=B.name,run_id=meta['run_id'],prompt_version='05_glossary_pass_a@v1',model='gpt-6.1-sol',generated_at=datetime.datetime.now(datetime.timezone.utc).isoformat(),source_snapshot_id=meta['source_snapshot_id'],parent_artifact_hashes={str(B/f):hashlib.sha256((B/f).read_bytes()).hexdigest() for f in inputs})
